$ErrorActionPreference = 'Stop'
$taskId = 'xdx-playbook-reconciliation-20261012'
$taskDir = "docs/builds/$taskId"
$checkpoint = [DateTime]::UtcNow.ToString('o')
Add-Content -LiteralPath "$taskDir/time-tracker.md" -Value "`nDelivery checkpoint: $checkpoint. Source review and all local policy/session/timing/package checks completed. Earlier pre-tracker reading remains unallocated. The interval between receipt refresh at 01:44:59Z and first host verification at 01:48:37Z includes approval/tool scheduling; no exact human-wait boundaries were retained, so its labor split is unknown. Command intervals are nested within task elapsed time. Final gate/commit/response tail is separately recorded by command receipts where observed and otherwise outside this checkpoint. No running tenant process, browser acceptance or human wait remains. Tokens/AI Units unavailable; no tenant calls performed."
Add-Content -LiteralPath "$taskDir/intake-and-learning-register.md" -Value "`nCloseout review: G001-G005 corrections and all scoped requirements reviewed against evidence. Reusable lifecycle refinements are in the existing playbook owners; operation warning is in Suppliers 26C and registry status; repository-only skill exclusion is within existing standing authority. No new autogenerated-field confirmation was observed. First GET sample is unchanged. Unverified benchmark CLI/state/code-field changes remain excluded. Cleanup decisions and local acceptance are in audit.md."
& node "$taskDir/maintain.cjs" startup
if ($LASTEXITCODE -ne 0) { throw 'Receipt refresh failed' }
$base = @('scripts/measure-build-command.cjs','--output',"$taskDir/commands.jsonl",'--task',$taskId,'--learning-ledger',"$taskDir/failure-ledger.json",'--learning-scope','governance')
$docs = @(& node @base --activity final-documents --phase closeout --category repair --label final-documents -- node "$taskDir/audit.cjs" verify 2>&1)
$docsCode = $LASTEXITCODE
[IO.File]::WriteAllText((Join-Path (Get-Location) "$taskDir/evidence/final-documents.txt"), ($docs -join "`n") + "`n")
if ($docsCode -ne 0) { throw 'Final documents failed' }
$record = Get-Content -Raw -LiteralPath "$taskDir/xdx_session_$taskId.json" | ConvertFrom-Json -DateKind String
$report = @(& node scripts/measure-build-command.cjs report --input "$taskDir/commands.jsonl" --from $record.startedUtc --to ([DateTime]::UtcNow.ToString('o')) 2>&1)
$reportCode = $LASTEXITCODE
[IO.File]::WriteAllText((Join-Path (Get-Location) "$taskDir/evidence/timing-report.json"), ($report -join "`n") + "`n")
if ($reportCode -ne 0) { throw 'Timing report failed; original output preserved in timing-report.json' }
& node "$taskDir/maintain.cjs" close-findings
if ($LASTEXITCODE -ne 0) { throw 'Finding closure failed' }
& node "$taskDir/maintain.cjs" closeout
if ($LASTEXITCODE -ne 0) { throw 'Closeout receipt refresh failed' }
$closeout = @(& node @base --activity closeout-gate --phase closeout --category closeout --label closeout-gate -- pwsh -NoProfile -File scripts/verify-living-build-contract.ps1 -SessionRecord "$taskDir/xdx_session_$taskId.json" -SessionId $taskId -Phase Closeout 2>&1)
$closeoutCode = $LASTEXITCODE
[IO.File]::WriteAllText((Join-Path (Get-Location) "$taskDir/evidence/closeout.txt"), ($closeout -join "`n") + "`n")
if ($closeoutCode -ne 0) { throw 'Closeout gate failed' }
Write-Output ($closeout -join "`n")
